        // Cross-section editorial review: History, Curiosities and Construction Details.
        const archiThreeSectionsEditorialAudit = {"history": {"world-wat-arun": {"index": 4, "es": "La ornamentación del templo fue ampliándose durante distintas campañas reales.", "en": "The temple's ornamentation expanded through successive royal building campaigns.", "it": "Le decorazioni del tempio furono ampliate durante diversi interventi reali."}, "world-puerta-de-brandeburgo": {"index": 2, "es": "La puerta sustituyó a un acceso anterior de las antiguas murallas de Berlín.", "en": "The gate replaced an earlier entrance in Berlin's former city walls.", "it": "La porta sostituì un precedente ingresso delle antiche mura di Berlino."}, "world-catedral-de-colonia": {"index": 4, "es": "Su escala monumental respondió al prestigio religioso y comercial de Colonia.", "en": "Its monumental scale reflected Cologne's religious and commercial prestige.", "it": "Le dimensioni monumentali riflettevano il prestigio religioso e commerciale di Colonia."}, "world-abadia-de-westminster": {"index": 4, "es": "La capilla de Enrique VII fue añadida durante el periodo Tudor.", "en": "Henry VII's Chapel was added during the Tudor period.", "it": "La cappella di Enrico VII fu aggiunta durante l'epoca Tudor."}, "world-tower-bridge": {"index": 3, "es": "El proyecto tuvo que conciliar el tránsito urbano con las necesidades de navegación.", "en": "The design had to reconcile road traffic with the needs of river navigation.", "it": "Il progetto dovette conciliare il traffico stradale con la navigazione fluviale."}, "world-atomium": {"index": 1, "es": "André Waterkeyn dirigió la concepción del pabellón para la Expo de 1958.", "en": "André Waterkeyn led the concept for the 1958 Expo pavilion.", "it": "André Waterkeyn guidò la concezione del padiglione per l'Expo del 1958."}, "world-burj-khalifa": {"index": 4, "es": "La construcción planteó nuevos desafíos logísticos de transporte vertical y bombeo de materiales.", "en": "Construction created new logistical challenges in vertical transport and pumping materials.", "it": "La costruzione pose nuove sfide logistiche nel trasporto verticale e nel pompaggio dei materiali."}, "world-templo-kinkaku-ji": {"index": 3, "es": "El pabellón fue concebido como espacio de retiro vinculado al poder del shōgun.", "en": "The pavilion was conceived as a retreat associated with the shogun's authority.", "it": "Il padiglione fu concepito come luogo di ritiro legato al potere dello shōgun."}, "world-acropolis-de-atenas": {"index": 0, "es": "La Acrópolis fue el principal recinto sagrado de la antigua Atenas.", "en": "The Acropolis was the principal sacred precinct of ancient Athens.", "it": "L'Acropoli era il principale recinto sacro dell'antica Atene."}, "world-bayon": {"index": 3, "es": "Las imágenes del templo reflejan la relación entre religión y autoridad real jemer.", "en": "The temple's imagery reflects the relationship between religion and Khmer royal power.", "it": "Le immagini del tempio riflettono il legame tra religione e potere reale khmer."}, "world-templos-de-bagan": {"index": 0, "es": "Bagan fue uno de los grandes centros religiosos del antiguo reino de Pagan.", "en": "Bagan was one of the major religious centers of the ancient Pagan kingdom.", "it": "Bagan fu uno dei grandi centri religiosi dell'antico regno di Pagan."}, "world-opera-de-sidney": {"index": 4, "es": "La obra exigió resolver numerosos desafíos técnicos durante su ejecución.", "en": "The project required solutions to numerous technical challenges during construction.", "it": "Il progetto richiese la soluzione di numerose sfide tecniche durante i lavori."}, "world-santorini-oia": {"index": 4, "es": "El paisaje urbano conserva huellas de la vida marítima y comercial de sus habitantes.", "en": "The townscape retains traces of its residents' maritime and commercial lives.", "it": "Il paesaggio urbano conserva tracce della vita marittima e commerciale degli abitanti."}, "world-machu-picchu": {"index": 5, "es": "El asentamiento integraba áreas residenciales, ceremoniales y de cultivo.", "en": "The settlement combined residential, ceremonial and agricultural areas.", "it": "L'insediamento comprendeva zone residenziali, cerimoniali e agricole."}, "world-templo-del-cielo": {"index": 3, "es": "El recinto se utilizaba para ceremonias estatales vinculadas al calendario agrícola.", "en": "The precinct was used for state ceremonies linked to the agricultural calendar.", "it": "Il recinto ospitava cerimonie di Stato legate al calendario agricolo."}}, "secret": {"world-lineas-de-nazca": {"es": "Una figura de Nazca conocida como «el astronauta» tiene una forma humana muy diferente de los grandes dibujos de animales.", "en": "A Nazca figure nicknamed 'the astronaut' has a human-like shape unlike the large animal drawings.", "it": "Una figura di Nazca soprannominata «l'astronauta» ha una forma umana molto diversa dai grandi disegni animali."}, "world-templo-de-karnak": {"es": "En Karnak, algunos obeliscos llevan inscripciones que celebran los logros de los faraones que ordenaron erigirlos.", "en": "At Karnak, some obelisks bear inscriptions celebrating the pharaohs who commissioned them.", "it": "A Karnak alcuni obelischi recano iscrizioni che celebrano i faraoni che li fecero erigere."}, "world-santorini-oia": {"es": "Oia fue un importante centro de capitanes y armadores; algunas de sus mansiones recuerdan aquella prosperidad marítima.", "en": "Oia was once a center for ship captains and owners; some mansions recall that maritime prosperity.", "it": "Oia fu un centro di capitani e armatori; alcune dimore ricordano quella prosperità marittima."}, "world-stonehenge": {"es": "Stonehenge fue comprado en una subasta en 1915 por Cecil Chubb, quien lo donó a la nación británica en 1918.", "en": "Stonehenge was bought at auction in 1915 by Cecil Chubb, who donated it to the British nation in 1918.", "it": "Stonehenge fu acquistato all'asta nel 1915 da Cecil Chubb, che lo donò alla nazione britannica nel 1918."}, "world-wat-arun": {"es": "El gran prang de Wat Arun fue ampliado durante el reinado de Rama III, cuando Bangkok consolidaba su nueva identidad como capital.", "en": "Wat Arun's great prang was enlarged under Rama III as Bangkok developed its identity as the new capital.", "it": "Il grande prang di Wat Arun fu ampliato sotto Rama III, mentre Bangkok consolidava la propria identità di capitale."}, "world-monte-fuji-santuario-fujisan": {"es": "El estanque Wakutama del santuario recibe agua que se filtra por la roca volcánica del monte Fuji antes de brotar en manantiales.", "en": "The shrine's Wakutama Pond receives water that filters through Mount Fuji's volcanic rock before emerging from springs.", "it": "Lo stagno Wakutama del santuario riceve acqua filtrata attraverso la roccia vulcanica del monte Fuji prima di sgorgare dalle sorgenti."}, "world-templos-de-bagan": {"es": "Un terremoto en 2016 dañó numerosos templos de Bagan y puso de relieve la fragilidad de sus estructuras históricas.", "en": "An earthquake in 2016 damaged many Bagan temples, highlighting the fragility of their historic structures.", "it": "Un terremoto nel 2016 danneggiò numerosi templi di Bagan, evidenziando la fragilità delle strutture storiche."}, "world-acropolis-de-atenas": {"es": "En el Erecteion de la Acrópolis, seis figuras femeninas conocidas como cariátides sustituyen a columnas convencionales en uno de los pórticos.", "en": "At the Acropolis's Erechtheion, six female figures called caryatids replace conventional columns on one porch.", "it": "Nell'Eretteo dell'Acropoli sei figure femminili dette cariatidi sostituiscono le colonne di un portico."}, "world-chichen-itza": {"es": "En el gran juego de pelota de Chichén Itzá, las paredes inclinadas incluyen anillos de piedra situados a considerable altura.", "en": "At Chichén Itzá's great ball court, the walls include stone rings set remarkably high.", "it": "Nel grande campo del gioco della palla di Chichén Itzá, le pareti includono anelli di pietra collocati molto in alto."}, "casa-batllo": {"es": "Los balcones de Casa Batlló recuerdan a máscaras o huesos, por lo que el edificio también recibe el apodo de «Casa de los Huesos».", "en": "Casa Batlló's balconies resemble masks or bones, earning it the nickname 'House of Bones'.", "it": "I balconi di Casa Batlló ricordano maschere o ossa: l'edificio è soprannominato «Casa delle Ossa»."}, "zytglogge": {"es": "Pocos minutos antes de cada hora, un pequeño desfile de figuras mecánicas cobra vida en la Zytglogge de Berna.", "en": "A few minutes before each hour, a small parade of mechanical figures comes to life at Bern's Zytglogge.", "it": "Pochi minuti prima di ogni ora, un piccolo corteo di figure meccaniche si anima sulla Zytglogge di Berna."}, "world-gran-palacio-de-bangkok": {"es": "En el Gran Palacio, el Buda Esmeralda no es de esmeralda: la pequeña imagen venerada está tallada en una piedra verde, habitualmente identificada como jade.", "en": "At the Grand Palace, the Emerald Buddha is not made of emerald: the revered image is carved from green stone, usually identified as jade.", "it": "Nel Grande Palazzo il Buddha di Smeraldo non è di smeraldo: la venerata immagine è scolpita in pietra verde, generalmente identificata come giada."}}, "architecture": {"colosseum": {"index": 2, "es": "Un sistema de unos 80 accesos facilitaba la entrada y salida del público.", "en": "A system of about 80 entrances helped crowds enter and leave.", "it": "Un sistema di circa 80 ingressi facilitava l'afflusso e il deflusso del pubblico."}, "borobudur": {"index": 1, "es": "El monumento reúne centenares de imágenes de Buda, tradicionalmente contabilizadas en 504.", "en": "The monument contains hundreds of Buddha images, traditionally counted as 504.", "it": "Il monumento comprende centinaia di immagini del Buddha, tradizionalmente conteggiate in 504."}, "chapel-bridge": {"index": 1, "es": "El puente cubierto tiene una longitud aproximada de 204 metros.", "en": "The covered bridge is approximately 204 meters long.", "it": "Il ponte coperto è lungo circa 204 metri."}, "arg-obelisco": {"index": 0, "es": "Una escalera interior de más de 200 peldaños permite subir hacia la parte superior.", "en": "An internal staircase of more than 200 steps leads toward the top.", "it": "Una scala interna di oltre 200 gradini conduce verso la sommità."}, "fr-notre-dame": {"index": 0, "es": "Las dos torres occidentales alcanzan aproximadamente 69 metros de altura.", "en": "The two western towers rise approximately 69 meters.", "it": "Le due torri occidentali raggiungono circa 69 metri di altezza."}, "fr-louvre": {"index": 2, "es": "La pirámide de vidrio de la entrada alcanza aproximadamente 21,6 metros de altura.", "en": "The glass entrance pyramid rises approximately 21.6 meters.", "it": "La piramide di vetro dell'ingresso raggiunge circa 21,6 metri."}, "fr-arc": {"index": 2, "es": "El arco alcanza aproximadamente 50 metros de altura.", "en": "The arch stands approximately 50 meters tall.", "it": "L'arco raggiunge circa 50 metri di altezza."}, "brasilia-cathedral": {"index": 2, "es": "La nave se sitúa en una planta circular de unos 70 metros de diámetro.", "en": "The nave occupies a circular plan about 70 meters across.", "it": "La navata occupa una pianta circolare di circa 70 metri di diametro."}}};
        initialMonumentsData.forEach(m => {
            const changes=archiThreeSectionsEditorialAudit;
            const h=changes.history[m.id];
            if(h){
                for(const [target,lang] of [[m,'es'],[englishMonumentContent[m.id],'en'],[italianMonumentContent[m.id],'it']]){
                    if(!target || typeof target.history!=='string') continue;
                    const lines=target.history.split('\n');
                    if(lines.length===8 && h.index<lines.length){
                        lines[h.index]=h[lang];
                        target.history=lines.join('\n');
                    }
                }
            }
            const c=changes.secret[m.id];
            if(c){
                m.secret=c.es;
                if(englishMonumentContent[m.id])englishMonumentContent[m.id].secret=c.en;
                if(italianMonumentContent[m.id])italianMonumentContent[m.id].secret=c.it;
            }
            const a=changes.architecture[m.id];
            if(a){
                for(const [target,lang] of [[m,'es'],[englishMonumentContent[m.id],'en'],[italianMonumentContent[m.id],'it']]){
                    if(target && Array.isArray(target.architecture) && target.architecture.length===3)
                        target.architecture[a.index]=a[lang];
                }
            }
        });


        const archiSettingsWords={
          es:['Ajustes','Personalizá tu experiencia','Idioma','Apariencia','Claro','Oscuro','Mi pasaporte','Acerca de ArchiSpotter','Cerrar sesión'],
          en:['Settings','Customize your experience','Language','Appearance','Light','Dark','My passport','About ArchiSpotter','Sign out'],
          it:['Impostazioni','Personalizza la tua esperienza','Lingua','Aspetto','Chiaro','Scuro','Il mio passaporto','Informazioni su ArchiSpotter','Esci']
        };
        function archiSyncSettings(){
          const lang=(typeof appLanguage!=='undefined'&&archiSettingsWords[appLanguage])?appLanguage:'es';
          const ids=['archi-settings-heading','archi-settings-subheading','archi-settings-lang-label','archi-settings-theme-label','archi-light-label','archi-dark-label','archi-settings-passport-label','archi-settings-about-label','archi-settings-logout-label'];
          ids.forEach((id,i)=>{const el=document.getElementById(id);if(el)el.textContent=archiSettingsWords[lang][i]});
          const devLabel=document.getElementById('archi-settings-dev-label');if(devLabel)devLabel.textContent=({es:'Modo desarrollador',en:'Developer mode',it:'Modalità sviluppatore'})[lang];
          const select=document.getElementById('archi-settings-language');if(select)select.value=lang;
          const light=document.body.classList.contains('light-mode');
          document.getElementById('archi-settings-light')?.setAttribute('aria-pressed',String(light));
          document.getElementById('archi-settings-dark')?.setAttribute('aria-pressed',String(!light));
        }
        function archiOpenSettings(){archiSyncSettings();const el=document.getElementById('archi-settings-overlay');if(el){el.hidden=false;el.querySelector('.archi-settings-close')?.focus();}}
        function archiCloseSettings(){const el=document.getElementById('archi-settings-overlay');if(el)el.hidden=true;}
        function archiSetTheme(theme){if(document.body.classList.contains('light-mode')!==(theme==='light'))toggleTheme();archiSyncSettings();}
        const archiAboutTranslations={
          es:{title:'Acerca de ArchiSpotter',message:'Esta app nació caminando por alguna calle del mundo, mirando edificios históricos y ruinas sin un cartel que explicara su historia. Porque sé que a vos, como a mí, la curiosidad no te deja quedarte con la duda de qué es eso que tienes ahí delante. ¡Bienvenidos a ArchiSpotter!',close:'Cerrar'},
          en:{title:'About ArchiSpotter',message:'This app was born while walking down a street somewhere in the world, looking at historic buildings and ruins without a sign explaining their history. Because I know that you, like me, are too curious to walk away without finding out what is right in front of you. Welcome to ArchiSpotter!',close:'Close'},
          it:{title:'Informazioni su ArchiSpotter',message:'Questa app è nata camminando per una strada in qualche parte del mondo, osservando edifici storici e rovine senza un cartello che ne spiegasse la storia. Perché so che tu, come me, sei troppo curioso per andare oltre senza scoprire che cosa hai davanti agli occhi. Benvenuti su ArchiSpotter!',close:'Chiudi'}
        };
        function archiSyncAboutLanguage(){
          const lang=(typeof appLanguage!=='undefined'&&archiAboutTranslations[appLanguage])?appLanguage:'es';
          const t=archiAboutTranslations[lang];
          const title=document.getElementById('archi-about-title');if(title)title.textContent=t.title;
          const message=document.getElementById('archi-about-message');if(message)message.textContent=t.message;
          const close=document.querySelector('#archi-about-overlay .archi-about-close');if(close)close.setAttribute('aria-label',t.close);
        }
        function archiShowAppInfo(){
          const overlay=document.getElementById('archi-about-overlay');
          if(overlay){archiSyncAboutLanguage();overlay.hidden=false;overlay.querySelector('.archi-about-close')?.focus();}
        }
        function archiCloseAppInfo(){const overlay=document.getElementById('archi-about-overlay');if(overlay)overlay.hidden=true;}

        document.addEventListener('keydown',e=>{if(e.key==='Escape')archiCloseSettings()});

        function tr(es,en){return appLanguage==='it'?(italianDynamicText[es]||en):appLanguage==='en'?en:es;}
